def apply(root):
    pending={}
    for rel,changes in PATCHES.items():
        p=root/rel
        if not p.is_file(): raise RuntimeError('No se encuentra '+rel+'. Coloca este instalador junto a la carpeta app.')
        text=p.read_text(encoding='utf-8')
        for old,new in changes:
            if text.count(old)==1: text=text.replace(old,new,1)
            elif text.count(new)==1: continue
            else: raise RuntimeError('Version diferente en '+rel+'. No se modifico ningun archivo. Envia tu ZIP actual para adaptar el parche.')
        ast.parse(text)
        pending[rel]=text
    backup=Path.home()/'NEGROSKY_RESPALDOS'
    backup.mkdir(exist_ok=True)
    path=backup/('antes_parche_sin_sucursal_'+datetime.now().strftime('%Y%m%d_%H%M%S_%f')+'.zip')
    with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED) as z:
        for rel in pending: z.write(root/rel,rel)
    for rel,text in pending.items():
        target=root/rel
        temp=target.with_suffix('.py.tmp')
        temp.write_text(text,encoding='utf-8')
        os.replace(temp,target)
    print('PARCHE APLICADO. Respaldo de codigo: '+str(path))
    print('Publica la carpeta COMPLETA de tu proyecto con el publicador rapido.')
    print('Antes de probar, conserva un respaldo de la base de datos desde tu proveedor.')
    print('La primera compra sin sucursal ajustara la tabla purchases para permitir branch_id vacio.')

if __name__=='__main__':
    try: apply(Path(__file__).resolve().parent)
    except Exception as e:
        print('ERROR: '+str(e))
        raise SystemExit(1)
